using System;
using System.Collections.Generic;
using System.Linq;
using CashflowChains.Economy;
namespace CashflowChains.City {
 public static class CityDayModel {
  sealed class Pool {public string Item;public int Source,X,Y,ReadyMinute;public long Quantity;}
  static int Distance(CityProperty a,CityProperty b)=>Math.Abs(a.X-b.X)+Math.Abs(a.Y-b.Y);
  static long Scale(long value,int bp)=>checked(value*(long)bp)/10000;
  public static CityDayResult Forecast(CityCatalog catalog,CityOperatingPlan plan){
   var r=new CityDayResult{Day=plan.Day,Season=new[]{"SPRING","SUMMER","AUTUMN","WINTER"}[((plan.Day-1)/7)%4]};var properties=plan.Properties.OrderBy(p=>p.Id).ToArray();var active=properties.Where(p=>p.Open).ToArray();r.HousingCapacity=CityPopulation.Capacity(catalog,active);r.Jobs=CityPopulation.Jobs(catalog,active);r.Population=CityPopulation.Residents(catalog,active,plan.GridTier);r.PayablesDue=plan.Payables;r.LoanDue=plan.Loans.Sum(l=>l.Due(plan.Day));
   int powerMade=active.Sum(p=>(int)catalog.Business(p.Kind).Outputs.Where(o=>o.ItemId=="ENERGY").Sum(o=>o.Quantity*p.Level));r.PowerDemand=active.Sum(p=>catalog.Business(p.Kind).Power*p.Level);r.PowerAvailable=catalog.GridCapacity*plan.GridTier+powerMade;r.PowerBasisPoints=r.PowerDemand==0?10000:Math.Min(10000,r.PowerAvailable*10000/r.PowerDemand);
   int transportVisitors=active.Where(p=>p.Kind=="port").Sum(p=>catalog.Business(p.Kind).Tourists*p.Level),beds=active.Where(p=>p.Kind=="hotel").Sum(p=>catalog.Business(p.Kind).Sales*p.Level);r.Visitors=Math.Min(beds,(int)Scale(transportVisitors,r.Season=="SUMMER"?12500:10000));
   int storage=catalog.BaseStorage+active.Sum(p=>catalog.Business(p.Kind).Storage*p.Level);int importCapacity=12+active.Sum(p=>catalog.Business(p.Kind).ImportCapacity*p.Level),exportCapacity=active.Sum(p=>catalog.Business(p.Kind).ExportCapacity*p.Level);long importBudget=plan.CashAvailable;int suppliesReady=0;var pools=new List<Pool>();
   CityResourceResult Resource(string id){var row=r.Resources.Find(s=>s.ItemId==id);if(row==null){row=new CityResourceResult{ItemId=id};r.Resources.Add(row);}return row;}
   var store=active.Where(p=>p.Kind=="warehouse"||p.Kind=="logistics").OrderBy(p=>p.Id).FirstOrDefault();foreach(var item in plan.Inventory){Resource(item.ItemId).Initial=item.Quantity;pools.Add(new Pool{Item=item.ItemId,Source=store?.Id??0,X=store?.X??0,Y=store?.Y??0,Quantity=item.Quantity});}
   CityBusinessResult Business(CityProperty p){var row=r.Businesses.Find(b=>b.PropertyId==p.Id);if(row==null){row=new CityBusinessResult{PropertyId=p.Id,Kind=p.Kind};r.Businesses.Add(row);}return row;}
   bool Use(CityProperty recipient,ItemAmount[] inputs,long operations,int minute){
    suppliesReady=minute;var purchases=new List<(string Item,long Missing,int Cost)>();long total=0;
    foreach(var input in inputs){long needed=checked(input.Quantity*operations),available=pools.Where(p=>p.Item==input.ItemId).Sum(p=>p.Quantity),missing=Math.Max(0,needed-available);if(missing==0)continue;var good=catalog.Goods.FirstOrDefault(g=>g.Id==input.ItemId);if(good==null||missing>importCapacity)return false;int cost=good.ImportPrice;if(plan.Partner=="local-roaster"&&plan.Day<=plan.PartnerEndsDay&&input.ItemId=="BEANS")cost=1;long charge=checked(missing*cost);total=checked(total+charge);purchases.Add((input.ItemId,missing,cost));}
    if(total>importBudget||purchases.Sum(p=>p.Missing)>importCapacity)return false;
    foreach(var purchase in purchases){importBudget-=purchase.Missing*purchase.Cost;importCapacity-=(int)purchase.Missing;Resource(purchase.Item).Imported+=purchase.Missing;r.ImportBills+=purchase.Missing*purchase.Cost;Business(recipient).Imports+=purchase.Missing*purchase.Cost;pools.Add(new Pool{Item=purchase.Item,Source=0,X=0,Y=0,Quantity=purchase.Missing,ReadyMinute=360});}
    foreach(var input in inputs){long remaining=checked(input.Quantity*operations);foreach(var pool in pools.Where(p=>p.Item==input.ItemId&&p.Quantity>0).OrderBy(p=>Math.Abs(p.X-recipient.X)+Math.Abs(p.Y-recipient.Y)).ThenBy(p=>p.Source)){long used=Math.Min(remaining,pool.Quantity);if(used==0)continue;pool.Quantity-=used;remaining-=used;Resource(input.ItemId).Consumed+=used;int distance=Math.Abs(pool.X-recipient.X)+Math.Abs(pool.Y-recipient.Y),travel=Math.Max(1,distance*(store==null?5:3));Business(recipient).DeliveryWork+=used*distance;suppliesReady=Math.Max(suppliesReady,pool.ReadyMinute+travel);r.Flows.Add(new CityFlow{Source=pool.Source,Target=recipient.Id,Kind=input.ItemId,Count=(int)used,Minute=Math.Max(pool.ReadyMinute,minute-travel),TravelMinutes=travel});if(remaining==0)break;}if(remaining!=0)throw new InvalidOperationException("Supply allocation failed");}
    return true;
   }
   foreach(var p in properties){var d=catalog.Business(p.Kind);var row=Business(p);row.Employees=p.Open?CityWorkforce.Staff(d,p):0;row.Advertising=p.Open?p.MarketingBudget:0;row.Bills=p.Open?Math.Max(2,d.FixedBills-d.BaseStaff*d.DailyWage)*p.Level+row.Employees*d.DailyWage+row.Advertising:Math.Min(2,d.FixedBills)*p.Level;r.Bills+=row.Bills;if(!p.Open)continue;if(d.Rent>0){row.Revenue=r.HousingCapacity==0?0:(long)Math.Floor(d.Rent*(decimal)p.Level*r.Population/r.HousingCapacity);r.Revenue+=row.Revenue;r.Flows.Add(new CityFlow{Source=p.Id,Target=0,Kind="RENT",Count=(int)row.Revenue,Minute=1080,TravelMinutes=1});}if(d.Power>0){int gridShare=r.PowerDemand==0?0:(int)Math.Ceiling(Math.Max(0,r.PowerDemand-powerMade)*(decimal)(d.Power*p.Level)/r.PowerDemand);long bill=Scale(gridShare*catalog.GridUnitCost,r.Season=="WINTER"?15000:10000);row.Bills+=bill;r.Bills+=bill;}}
   // Producers operate before customer service. Inputs and outputs are finite;
   // imports reserve a published cash budget and cannot be exported for profit.
   foreach(var p in active.Where(p=>catalog.Business(p.Kind).Outputs.Length>0).OrderBy(p=>catalog.Business(p.Kind).Inputs.Length).ThenBy(p=>p.Id)){var d=catalog.Business(p.Kind);if(d.Kind=="power")continue;int operations=(int)Scale(Scale(p.Level*10000L,CityWorkforce.Productivity(d,p)),r.PowerBasisPoints)/10000;if(operations==0||!Use(p,d.Inputs,operations,420))continue;foreach(var output in d.Outputs){int season=p.Kind=="farm"?(r.Season=="WINTER"?7500:r.Season=="SPRING"?11000:10000):10000;long made=Scale(output.Quantity*operations,season);Resource(output.ItemId).Produced+=made;pools.Add(new Pool{Item=output.ItemId,Quantity=made,Source=p.Id,X=p.X,Y=p.Y,ReadyMinute=420});}}
   var capacities=active.Where(p=>catalog.Business(p.Kind).Sales>0).ToDictionary(p=>p.Id,p=>(int)Scale(Scale(catalog.Business(p.Kind).Sales*p.Level,CityWorkforce.Productivity(catalog.Business(p.Kind),p)),r.PowerBasisPoints));
   void Serve(CityProperty home,string family,int demand,int opening){
    if(demand<=0)return;if(family=="coffee")r.CoffeeDemand+=demand;var shops=active.Where(p=>catalog.Business(p.Kind).Family==family&&capacities[p.Id]>0).ToArray();if(shops.Length==0){r.CompetitorCustomers+=demand;return;}
    var scores=shops.ToDictionary(p=>p.Id,p=>(decimal)(10000+active.Count(a=>a.Kind=="park"&&Distance(a,p)<=2)*1000+(p.MarketingBudget==5?1500:p.MarketingBudget==15?5000:0))/(Math.Max(1,catalog.Business(p.Kind).Price*p.PriceBasisPoints/10000)*10+Distance(home,p)*5+20));decimal total=catalog.CompetitorWeight+scores.Values.Sum();int remaining=demand;
    foreach(var shop in shops.OrderBy(p=>Distance(home,p)).ThenBy(p=>p.Id)){var d=catalog.Business(shop.Kind);Business(shop).PotentialCustomers+=demand;int quantity=Math.Min(remaining,Math.Min(capacities[shop.Id],(int)Math.Floor(demand*scores[shop.Id]/total)));if(quantity<=0)continue;int arrivals=opening+Distance(home,shop)*5;for(int served=0;served<quantity;served++){if(!Use(shop,d.Inputs,1,arrivals))break;long value=Math.Max(1,d.Price*(long)shop.PriceBasisPoints/10000);var row=Business(shop);row.Customers++;row.Revenue+=value;r.Revenue+=value;capacities[shop.Id]--;remaining--;if(family=="coffee")r.CoffeeServed++;r.Flows.Add(new CityFlow{Source=home.Id,Target=shop.Id,Kind="CUSTOMER",Count=1,Minute=opening+served*5,TravelMinutes=Distance(home,shop)*5});r.Flows.Add(new CityFlow{Source=shop.Id,Target=home.Id,Kind=family=="coffee"?"COFFEE":"SERVICE",Count=1,Minute=Math.Max(suppliesReady,arrivals+served*5)+1,TravelMinutes=1});r.Flows.Add(new CityFlow{Source=home.Id,Target=shop.Id,Kind="CASH",Count=(int)value,Minute=Math.Max(suppliesReady,arrivals+served*5)+1,TravelMinutes=1});}}
    r.CompetitorCustomers+=remaining;
   }
   foreach(var home in active.Where(p=>catalog.Business(p.Kind).Population>0)){int pop=r.HousingCapacity==0?0:catalog.Business(home.Kind).Population*home.Level*r.Population/r.HousingCapacity;Serve(home,"coffee",pop/2,480);Serve(home,"shopping",pop/3,720);Serve(home,"services",pop/6,600);Serve(home,"entertainment",pop/6,1140);}
   if(r.Visitors>0){var dock=active.First(p=>p.Kind=="port");Serve(dock,"stay",r.Visitors,900);Serve(dock,"coffee",r.Visitors/2,960);}
   if(plan.Partner=="local-roaster"&&plan.Day<=plan.PartnerEndsDay)r.Bills+=5;if(plan.Sponsor=="coffee-fair"&&plan.Day<=plan.SponsorEndsDay){r.Bills+=8;if(r.CoffeeServed>=5){r.SponsorshipRevenue=20;r.Revenue+=20;}}
   foreach(var business in r.Businesses){business.DeliveryBills=(business.DeliveryWork+(store==null?19:29))/(store==null?20:30);business.Bills+=business.DeliveryBills;r.Bills+=business.DeliveryBills;}
   foreach(var business in r.Businesses.Where(b=>b.Kind!="home")){business.Tax=Scale(business.Revenue,catalog.TaxBasisPoints);r.Tax+=business.Tax;}
   foreach(var good in catalog.Goods){var row=Resource(good.Id);long available=pools.Where(p=>p.Item==good.Id).Sum(p=>p.Quantity);long reserve=Math.Max(8,row.Consumed);long surplus=Math.Max(0,Math.Min(available-reserve,row.Initial+row.Produced-row.Consumed));long exported=good.ExportPrice<=0?0:Math.Min(exportCapacity,surplus);if(exported>0){row.Exported=exported;exportCapacity-=(int)exported;r.ExportRevenue+=exported*good.ExportPrice;r.Flows.Add(new CityFlow{Source=store?.Id??0,Target=0,Kind="EXPORT",Count=(int)exported,Minute=1200,TravelMinutes=30});available-=exported;}row.Spilled=Math.Max(0,available-storage);row.Closing=available-row.Spilled;}
   r.Revenue+=r.ExportRevenue;foreach(var row in r.Resources.Where(x=>!catalog.Goods.Any(g=>g.Id==x.ItemId)))row.Closing=row.Initial+row.Produced+row.Imported-row.Consumed-row.Exported-row.Spilled;
   foreach(var row in r.Resources)if(row.Initial+row.Produced+row.Imported!=row.Consumed+row.Exported+row.Spilled+row.Closing||row.Closing<0)throw new InvalidOperationException("City resources not conserved");return r;
  }
 }
}
